export default MainLayout;
=== src/styles/index.css
@import "tailwindcss";

@theme {
	--font-sans:
		ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
		"Helvetica Neue", Arial, sans-serif;
	/* Deep teal brand. 600 on white is 5.1:1, so it is safe for text and buttons. */
	--color-brand-50: #eef8f6;
	--color-brand-100: #d7efea;
	--color-brand-200: #b2ded6;
	--color-brand-500: #1f9590;
	--color-brand-600: #137b79;
	--color-brand-700: #0f6663;
	--color-brand-800: #0d4f50;
	--color-brand-900: #0b363d;
	--color-canvas: #f4f7f8;
	--shadow-panel: 0 14px 42px rgb(18 50 58 / 0.06);
}

:root {
	/*
	 * Payment breakdown series, read through var() in inline styles, so they
	 * live outside @theme (Tailwind drops theme variables no utility uses).
	 * Each series is also named in text next to its color.
	 */
	--color-series-pi: #137b79;
	--color-series-tax: #5b7fc7;
	--color-series-insurance: #e0a55a;
	--color-series-pmi: #b0558f;
	--color-series-hoa: #8fa6ab;
	--color-series-other: #c7d3d6;
	--chart-hypothetical: #fffbeb;
	--chart-grid: #e2e8f0;
	--chart-base-line: #64748b;
}

html {
	/* Keeps focused fields clear of the mobile summary bar (WCAG 2.4.11). */
	scroll-padding-bottom: 6rem;
}

@media (prefers-reduced-motion: no-preference) {
	html {
		scroll-behavior: smooth;
	}
}

@media (prefers-reduced-motion: reduce) {
	*,
	::before,
	::after {
		animation-duration: 0.01ms;
		animation-iteration-count: 1;
		transition-duration: 0.01ms;
	}
}

body {
	background-color: var(--color-canvas);
	color: var(--color-slate-900);
	font-family: var(--font-sans);
	-webkit-font-smoothing: antialiased;
}

/* One visible focus style for every control that has no ring of its own. */
:where(a, button, summary, select, [tabindex]):focus-visible {
	outline: 3px solid var(--color-brand-500);
	outline-offset: 2px;
}

/* `<details>` markers are drawn by the AdvancedSection component. */
summary::-webkit-details-marker {
	display: none;
}

@media print {
	@page {
		margin: 15mm;
	}

	html {
		scroll-padding-bottom: 0;
	}

	body {
		background-color: white;
	}

	/* Browsers repeat these groups on every printed page. */
	thead {
		display: table-header-group;
	}

	tfoot {
		display: table-footer-group;
	}
}
=== src/components/ui/Button.tsx
import type { ButtonHTMLAttributes } from "react";
import { cn } from "@/lib/cn";

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
	variant?: "primary" | "secondary";
}

const variants = {
	primary: "bg-brand-600 text-white hover:bg-brand-700",
	secondary:
		"bg-white text-slate-900 ring-1 ring-slate-300 hover:bg-slate-50 hover:ring-slate-400",
} as const;

const Button = ({
	variant = "primary",
	className,
	type = "button",
	...props
}: ButtonProps) => (
	<button
		type={type}
		className={cn(
			"inline-flex items-center justify-center rounded-lg px-4 py-2 text-sm font-semibold motion-safe:transition-colors focus-visible:outline-3 focus-visible:outline-offset-2 focus-visible:outline-brand-500 disabled:opacity-50",
			variants[variant],
			className,
		)}
		{...props}
	/>
);

export default Button;
