import { useId } from "react";
import { cn } from "@/lib/cn";

interface TextFieldProps {
	label: string;
	value: string;
	onChange: (value: string) => void;
	onBlur: () => void;
	error?: string | undefined;
	hint?: string;
	prefix?: string;
	suffix?: string;
	readOnly?: boolean;
	className?: string;
}

const TextField = ({
	label,
	value,
	onChange,
	onBlur,
	error,
	hint,
	prefix,
	suffix,
	readOnly = false,
	className,
}: TextFieldProps) => {
	const id = useId();
	const errorId = `${id}-error`;
	const hintId = `${id}-hint`;
	const describedBy =
		[error ? errorId : null, hint ? hintId : null].filter(Boolean).join(" ") ||
		undefined;

	return (
		<div className={className}>
			<label
				htmlFor={id}
				className="block text-sm font-semibold text-slate-800"
			>
				{label}
			</label>
			<div
				className={cn(
					"mt-1.5 flex min-h-12 items-center rounded-xl bg-white ring-1 ring-slate-300 motion-safe:transition-shadow hover:ring-slate-400 focus-within:ring-3 focus-within:ring-brand-500",
					error &&
						"ring-2 ring-red-600 hover:ring-red-600 focus-within:ring-red-600",
					readOnly && "bg-slate-50 text-slate-600 hover:ring-slate-300",
				)}
			>
				{prefix ? (
					<span
						aria-hidden="true"
						className="pl-3.5 font-semibold text-slate-500"
					>
						{prefix}
					</span>
				) : null}
				<input
					id={id}
					type="text"
					inputMode="decimal"
					autoComplete="off"
					value={value}
					readOnly={readOnly}
					aria-readonly={readOnly || undefined}
					aria-invalid={error ? true : undefined}
					aria-describedby={describedBy}
					onChange={(event) => onChange(event.target.value)}
					onBlur={onBlur}
					className="w-full min-w-0 bg-transparent px-3 py-2 text-base font-semibold text-slate-900 tabular-nums outline-none"
				/>
				{suffix ? (
					<span
						aria-hidden="true"
						className="pr-3.5 font-semibold text-slate-500"
					>
						{suffix}
					</span>
				) : null}
			</div>
			{hint ? (
				<p
					id={hintId}
					className="mt-1.5 text-xs leading-relaxed text-slate-600"
				>
					{hint}
				</p>
			) : null}
			{error ? (
				<p
					id={errorId}
					role="alert"
					className="mt-1 text-sm font-medium text-red-700"
				>
					<span aria-hidden="true">⚠ </span>
					{error}
				</p>
			) : null}
		</div>
	);
};

export default TextField;
import { type ReactNode, useEffect, useRef, useState } from "react";

interface AdvancedSectionProps {
	title: string;
	description: string;
	/** Visible errors inside the section. The section opens when one appears. */
	errorCount?: number;
	defaultOpen?: boolean;
	children: ReactNode;
}

/**
 * A collapsible group of optional inputs. Uses native `<details>`, so it is
 * keyboard and screen reader friendly without extra ARIA. The summary shows
 * an error count in text, so a closed section never hides a problem.
 */
const AdvancedSection = ({
	title,
	description,
	errorCount = 0,
	defaultOpen = false,
	children,
}: AdvancedSectionProps) => {
	const [open, setOpen] = useState(defaultOpen);
	const previousErrors = useRef(errorCount);
	useEffect(() => {
		// Open when an error first appears, for example a credit that became too
		// large after the down payment changed elsewhere.
		if (errorCount > 0 && previousErrors.current === 0) setOpen(true);
		previousErrors.current = errorCount;
	}, [errorCount]);

	return (
		<details
			open={open}
			onToggle={(event) => setOpen(event.currentTarget.open)}
			className="group border-t border-slate-200"
		>
			<summary className="flex min-h-14 cursor-pointer list-none items-center justify-between gap-3 rounded-lg py-3 hover:text-brand-700">
				<span className="min-w-0">
					<span className="block text-sm font-bold text-slate-900">
						{title}
					</span>
					<span className="block text-xs text-slate-600">{description}</span>
				</span>
				<span className="flex shrink-0 items-center gap-2">
					{errorCount > 0 ? (
						<span className="rounded-full bg-red-50 px-2 py-0.5 text-xs font-semibold text-red-800 ring-1 ring-red-300">
							<span aria-hidden="true">⚠ </span>
							{errorCount === 1 ? "1 issue" : `${errorCount} issues`}
						</span>
					) : null}
					<svg
						aria-hidden="true"
						viewBox="0 0 20 20"
						className="size-5 text-brand-600 motion-safe:transition-transform group-open:rotate-180"
					>
						<path
							d="M5 7.5l5 5 5-5"
							fill="none"
							stroke="currentColor"
							strokeWidth={2}
							strokeLinecap="round"
							strokeLinejoin="round"
						/>
					</svg>
				</span>
			</summary>
			<div className="grid gap-5 pt-2 pb-6 sm:grid-cols-2">{children}</div>
		</details>
	);
};

export default AdvancedSection;
const MonthlyPaymentHero = ({
	estimate,
	arm,
	outOfDate = false,
	stale = false,
}: MonthlyPaymentHeroProps) => (
	<section
		aria-labelledby="monthly-estimate-heading"
		className="overflow-hidden rounded-2xl bg-linear-135 from-brand-900 to-brand-800 p-1.5 text-white shadow-panel sm:p-2"
	>
		<div className="px-4 pt-4 pb-5 sm:px-5 sm:pt-5">
			<div className="flex flex-wrap items-start justify-between gap-2">
				<h2
					id="monthly-estimate-heading"
					className="text-xs font-bold tracking-widest text-brand-100 uppercase"
				>
					Estimated monthly cost
				</h2>
				{estimate ? <StatusPill stale={stale} arm={Boolean(arm)} /> : null}
			</div>
			<div aria-live="polite">
				{estimate ? (
					<>
						<p className="mt-2 text-4xl font-extrabold tracking-tight tabular-nums sm:text-5xl">
							{formatMoney(estimate.total)}
							<span className="ml-2 text-base font-medium tracking-normal text-brand-100">
								/ month total
							</span>
						</p>
						<p className="mt-1 text-sm text-brand-100">
							Principal, interest, taxes, insurance and other ownership costs
						</p>
					</>
				) : (
					<p className="mt-2 text-base text-white">
						Fix the highlighted fields to see the itemized monthly estimate.
					</p>
				)}
			</div>
		</div>
		<div className="rounded-xl bg-white p-4 text-slate-900 sm:p-5">
			{estimate ? (
				<>
					<PaymentBreakdown
						estimate={estimate}
						piLabel={arm ? "Principal and interest (months 1–60)" : undefined}
					/>
					{arm ? <ResetRisk arm={arm} /> : null}
					{outOfDate ? (
						<p className="mt-4 text-sm text-amber-950">
							<span className="rounded bg-amber-100 px-1.5 py-0.5 text-xs font-semibold ring-1 ring-amber-400">
								May be out of date
							</span>{" "}
							Some illustrative defaults behind this estimate are over a year
							old. See the assumptions below.
						</p>
					) : null}
				</>
			) : null}
			<div className={estimate ? "mt-5" : undefined}>
				<Disclaimer />
			</div>
		</div>
	</section>
);

export default MonthlyPaymentHero;

