						<ScenarioFields
							key={TITLES[index]}
							title={TITLES[index]}
							scenario={state.scenarios[index]}
							rateError={
								touched[index === 0 ? "rate0" : "rate1"]
									? comparison.scenarios[index].errors.interestRate
									: undefined
							}
