								touched[index === 0 ? "rate0" : "rate1"]
									? comparison.scenarios[index].errors.interestRate
									: undefined
							}
							onChange={(patch) => setScenario(index, patch)}
							onRateBlur={() => touch(index === 0 ? "rate0" : "rate1")}
						/>
					))}
				</div>
			</Card>
			<CompareResults titles={TITLES} comparison={comparison} />
			<Disclaimer />
		</div>
	);
