	lower: 0 | 1 | null;
	/** Absolute difference in cents, when both values exist. */
	difference: Cents | null;
}

const lowerOf = (a: Cents | null, b: Cents | null): 0 | 1 | null => {
	if (a === null || b === null || a === b) return null;
	return a < b ? 0 : 1;
};

