			downPaymentPercent: "20",
			loanType: "fixed",
			termYears: 15,
			interestRate: "6.50",
			armIndexPreset: "flat",
		},
		{
			homePrice: "500,000",
			downPaymentPercent: "20",
			loanType: "fixed",
			termYears: 30,
			interestRate: "6.50",
			armIndexPreset: "flat",
		},
	],
};

/** Loan A and Loan B trade places. */
export const swapScenarios = (state: CompareState): CompareState => ({
	scenarios: [state.scenarios[1], state.scenarios[0]],
});

