import type { ReactNode } from "react";
import { cn } from "@/lib/cn";
import { LOAN_LABELS, LOAN_STYLE } from "../loanStyle";

export type RowPosition = "first" | "middle" | "last";

interface CompareRowProps {
	/** Names the section for screen readers, for example "Home". */
	label: string;
	position: RowPosition;
	/** Loan shown below the desktop breakpoint. */
	active: 0 | 1;
	cells: [ReactNode, ReactNode];
	/** Pins the row to the top of the screen on desktop. */
	sticky?: boolean;
}

const CELL =
	"min-w-0 border-x border-slate-200 bg-white px-4 py-4 sm:px-6";

const EDGE: Record<RowPosition, string> = {
	first:
		"rounded-t-2xl border-t-4 pt-5 border-x-slate-200 shadow-panel",
	middle: "border-t border-t-slate-100",
	last: "rounded-b-2xl border-b border-b-slate-200 border-t border-t-slate-100 pb-6",
};

/**
 * One row of the comparison grid: the same section for Loan A and Loan B,
 * side by side from `lg` up so matching fields line up. Below `lg` only the
 * active loan's cell is shown; the other stays mounted in state, never lost.
 */
const CompareRow = ({
	label,
	position,
	active,
	cells,
	sticky = false,
}: CompareRowProps) => (
	<>
		{([0, 1] as const).map((index) => (
			<div
				key={LOAN_LABELS[index]}
				role="group"
				aria-label={`${LOAN_LABELS[index]}: ${label}`}
				className={cn(
					CELL,
					EDGE[position],
					position === "first" && LOAN_STYLE[index].accent,
					sticky && "lg:sticky lg:top-0 lg:z-20",
					index !== active && "hidden lg:block",
				)}
			>
				{cells[index]}
			</div>
		))}
	</>
);

export default CompareRow;
