					<Button variant="secondary" onClick={duplicate}>
						<Icon name="copy" className="size-4" />
						Copy Loan A to Loan B
					</Button>
				</div>
			</div>
			<p role="status" className="sr-only">
				{notice}
			</p>

			<CompareSummary state={deferred} comparison={comparison} />

			<LoanSwitch
				active={active}
				onChange={setActive}
				comparison={comparison}
			/>

			<form
				noValidate
				onSubmit={(event) => event.preventDefault()}
				aria-label="Loan comparison"
				className="grid grid-cols-1 lg:grid-cols-2 lg:gap-x-6"
			>
				<CompareRow
					label="Summary"
					position="first"
					active={active}
					sticky
					cells={[0, 1].map((index) => (
						<HeaderCell
							key={index}
							index={index as 0 | 1}
							scenario={state.scenarios[index as 0 | 1]}
							result={comparison.scenarios[index as 0 | 1]}
						/>
					)) as [React.ReactNode, React.ReactNode]}
				/>
				<CompareRow
					label="Home"
					position="middle"
					active={active}
					cells={([0, 1] as const).map((index) => (
						<HomeCell
							key={index}
							scenario={state.scenarios[index]}
							priceError={shown(
								index,
								"homePrice",
								comparison.scenarios[index].errors.homePrice,
							)}
							downError={shown(
								index,
								"downPayment",
								comparison.scenarios[index].errors.downPayment,
							)}
							onChange={(patch) => setScenario(index, patch)}
							onPriceBlur={() => touch(index, "homePrice")}
							onDownBlur={() => touch(index, "downPayment")}
						/>
					)) as [React.ReactNode, React.ReactNode]}
				/>
				<CompareRow
					label="Loan"
					position="middle"
					active={active}
					cells={([0, 1] as const).map((index) => (
						<LoanCell
							key={index}
							scenario={state.scenarios[index]}
							onChange={(patch) => setScenario(index, patch)}
						/>
					)) as [React.ReactNode, React.ReactNode]}
				/>
				<CompareRow
					label="Rate"
					position="middle"
					active={active}
					cells={([0, 1] as const).map((index) => (
						<RateCell
							key={index}
							scenario={state.scenarios[index]}
							rateError={shown(
								index,
								"rate",
								comparison.scenarios[index].errors.interestRate,
							)}
							onChange={(patch) => setScenario(index, patch)}
							onRateBlur={() => touch(index, "rate")}
						/>
					)) as [React.ReactNode, React.ReactNode]}
				/>
				{(["monthly", "upfront", "lifetime"] as const).map((section, i, all) => (
					<CompareRow
						key={section}
						label={SECTION_LABEL[section]}
						position={i === all.length - 1 ? "last" : "middle"}
						active={active}
						cells={([0, 1] as const).map((index) => (
							<div key={index}>
								<h3 className="mb-2 text-xs font-bold tracking-widest text-slate-600 uppercase">
									{SECTION_LABEL[section]}
								</h3>
								<ResultCell
									section={section}
									index={index}
									result={comparison.scenarios[index]}
									isLower={lowerFor(index)}
								/>
							</div>
						)) as [React.ReactNode, React.ReactNode]}
					/>
				))}
			</form>

			<SavedScenarios
				kind="compare"
				current={state}
				parse={parseCompareState}
				onOpen={(saved) => {
					setState(saved);
					setTouched(noneTouched);
				}}
				{...(storage !== undefined ? { storage } : {})}
			/>
			<Disclaimer />
		</div>
	);
};

const SECTION_LABEL = {
	monthly: "Monthly cost",
	upfront: "Upfront",
	lifetime: "Over the life of the loan",
} as const;

export default CompareView;
