import {
	cleanup,
	fireEvent,
	render,
	screen,
	within,
} from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";
import CompareView from "./CompareView";

afterEach(cleanup);

/** One loan's section, for example group("Loan B", "Rate"). */
const group = (loan: string, section: string) =>
	within(screen.getByRole("group", { name: `${loan}: ${section}` }));
const summary = () =>
	within(screen.getByRole("region", { name: /differences at a glance/i }));

describe("CompareView", () => {
