const mk=(w)=>new Promise(r=>{const f=document.createElement('iframe');f.style.cssText=`width:${w}px;height:900px;border:0;display:block`;f.src='/compare';f.onload=()=>setTimeout(()=>r(f),1500);document.body.innerHTML='';document.body.appendChild(f);});
const out={};
for(const w of [360,768,1024,1280,1920]){const f=await mk(w);const d=f.contentDocument,de=d.documentElement;
