const aligned2=!cols.some(c=>c.offsetParent===null)?rows2[0].every((t,i)=>t===rows2[1][i]):'one-col';
out[w]={overflow:de.scrollWidth-de.clientWidth,aligned,alignedWithArmB:aligned2};}
